import { Component, inject, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { HttpErrorResponse } from '@angular/common/http';

import { RegimeService, Regime, RegimeCreateUpdateRequest } from '../../../services/regime.service';
import { ToastService } from '../../../services/toast.service';
import { AuthenticatedLayoutComponent } from '../../../shared/layouts/authenticated-layout/authenticated-layout.component';
import { ConfirmModalComponent } from '../../../shared/components/confirm-modal/confirm-modal.component';
import { ModalComponent } from '../../../shared/components/modal/modal.component';
import { DatatableComponent } from '../../../shared/components/datatable/datatable.component';

@Component({
  selector: 'app-regime',
  standalone: true,
  imports: [CommonModule, FormsModule, AuthenticatedLayoutComponent, ConfirmModalComponent, ModalComponent, DatatableComponent],
  templateUrl: './regime.component.html',
  styleUrls: ['./regime.component.scss'],
})
export class RegimeComponent implements OnInit {
  private readonly regimeService: RegimeService = inject(RegimeService);
  private readonly toastService: ToastService = inject(ToastService);

  regimes: Regime[] = [];
  inEdition: number = 0;
  isLoader: boolean = false;
  processing: boolean = false;
  showModal: boolean = false;
  errors: any = {};

  // Pagination and Filtering state
  pagination: any = {
    current_page: 1,
    per_page: 10,
    total: 0,
    last_page: 1,
    from: 0,
    to: 0,
  };
  searchQuery: string = '';
  sortColumn: string = 'id';
  sortDirection: string = 'desc';

  form = {
    id: 0,
    name: '',
  };

  ngOnInit(): void {
    this.loadRegimes();
  }

  /**
   * Carregar lista de regimes com paginação e filtros
   */
  loadRegimes(): void {
    this.isLoader = true;
    const params = {
      page: this.pagination.current_page,
      per_page: this.pagination.per_page,
      search: this.searchQuery,
      sort_column: this.sortColumn,
      sort_direction: this.sortDirection,
    };

    this.regimeService.getRegimes(params).subscribe({
      next: (response: any) => {
        this.regimes = response.data || [];
        this.pagination = {
          current_page: response.current_page,
          per_page: response.per_page,
          total: response.total,
          last_page: response.last_page,
          from: response.from,
          to: response.to,
        };
        this.isLoader = false;
      },
      error: (error: HttpErrorResponse) => {
        this.isLoader = false;
        this.toastService.error('Erro ao carregar regimes');
        console.error('Erro ao carregar regimes:', error);
      },
    });
  }

  /**
   * Pesquisar (chamado pelo DatatableComponent)
   */
  onSearch(query: string): void {
    this.searchQuery = query;
    this.pagination.current_page = 1;
    this.loadRegimes();
  }

  /**
   * Mudar página (chamado pelo DatatableComponent)
   */
  onPageChange(page: number): void {
    this.pagination.current_page = page;
    this.loadRegimes();
  }

  /**
   * Mudar quantidade por página (chamado pelo DatatableComponent)
   */
  onPerPageChange(perPage: number): void {
    this.pagination.per_page = perPage;
    this.pagination.current_page = 1;
    this.loadRegimes();
  }

  /**
   * Ordenar coluna
   */
  sortBy(column: string): void {
    if (this.sortColumn === column) {
      this.sortDirection = this.sortDirection === 'asc' ? 'desc' : 'asc';
    } else {
      this.sortColumn = column;
      this.sortDirection = 'asc';
    }
    this.loadRegimes();
  }

  openModal(): void {
    this.resetForm();
    this.showModal = true;
  }

  closeModal(): void {
    this.showModal = false;
    this.resetForm();
  }

  /**
   * Editar regime
   */
  edit(regime: Regime): void {
    this.inEdition = regime.id;
    this.form.id = regime.id;
    this.form.name = regime.name;
    this.errors = {};
    this.showModal = true;
  }

  /**
   * Cancelar edição
   */
  cancelEdit(): void {
    this.closeModal();
  }

  /**
   * Resetar formulário
   */
  resetForm(): void {
    this.form = {
      id: 0,
      name: '',
    };
    this.errors = {};
    this.inEdition = 0;
    this.processing = false;
  }

  /**
   * Validar formulário
   */
  private validateForm(): boolean {
    this.errors = {};

    if (!this.form.name || this.form.name.trim() === '') {
      this.errors.name = ['O nome é obrigatório'];
    }

    return Object.keys(this.errors).length === 0;
  }

  /**
   * Salvar regime (criar ou atualizar)
   */
  submit(): void {
    if (!this.validateForm()) {
      return;
    }

    this.processing = true;

    const data: RegimeCreateUpdateRequest = {
      id: this.form.id,
      name: this.form.name,
    };

    this.regimeService.saveRegime(data).subscribe({
      next: (response: any) => {
        this.processing = false;
        this.toastService.success(response.message || 'Regime salvo com sucesso');
        this.closeModal();
        this.loadRegimes();
      },
      error: (error: HttpErrorResponse) => {
        this.processing = false;
        if (error.status === 422) {
          this.errors = error.error.errors || {};
        } else {
          this.toastService.error('Erro ao salvar regime');
        }
        console.error('Erro ao salvar regime:', error);
      },
    });
  }

  /**
   * Deletar regime
   */
  deleteRegime(regimeId: number): void {
    this.isLoader = true;
    this.regimeService.deleteRegime(regimeId).subscribe({
      next: (response: any) => {
        this.isLoader = false;
        this.toastService.success(response.message || 'Regime apagado com sucesso');
        this.loadRegimes();
      },
      error: (error: HttpErrorResponse) => {
        this.isLoader = false;
        this.toastService.error('Erro ao apagar regime');
        console.error('Erro ao deletar regime:', error);
      },
    });
  }

  /**
   * Ativar regime
   */
  activateRegime(regimeId: number): void {
    this.isLoader = true;
    this.regimeService.activateRegime(regimeId).subscribe({
      next: (response: any) => {
        this.isLoader = false;
        this.toastService.success(response.message || 'Regime ativado com sucesso');
        this.loadRegimes();
      },
      error: (error: HttpErrorResponse) => {
        this.isLoader = false;
        this.toastService.error('Erro ao ativar regime');
        console.error('Erro ao ativar regime:', error);
      },
    });
  }

  /**
   * Inativar regime
   */
  deactivateRegime(regimeId: number): void {
    this.isLoader = true;
    this.regimeService.deactivateRegime(regimeId).subscribe({
      next: (response: any) => {
        this.isLoader = false;
        this.toastService.success(response.message || 'Regime inativado com sucesso');
        this.loadRegimes();
      },
      error: (error: HttpErrorResponse) => {
        this.isLoader = false;
        this.toastService.error('Erro ao inativar regime');
        console.error('Erro ao inativar regime:', error);
      },
    });
  }

  /**
   * Método auxiliar para template
   */
  isRegimeInEdition(regimeId: number): boolean {
    return this.inEdition === regimeId;
  }
}
